select count(1) count
from contract t
left join contract tt on t.contract_parent_id = tt.contract_id and tt.status_cd = '0' and tt.store_id =
t.store_id
left join contract_type_template ctt on t.template_id = ctt.template_id and ctt.status_cd = '0' and ctt.store_id =
t.store_id
where 1 =1

    and t.a_link= #{aLink}


    and t.a_contacts= #{aContacts}


    and t.amount= #{amount}


    and t.status_cd= #{statusCd}


    and t.store_id= #{storeId}


    and t.operator= #{operator}


    and t.signing_time= #{signingTime}


    and t.b_contacts= #{bContacts}


    and t.party_a= #{partyA}


    and t.b_link= #{bLink}


    and t.party_b= #{partyB}


    and t.party_b like concat('%',#{partyBLike},'%')


    and t.contract_id= #{contractId}


    and t.contract_id in

        #{item}



    and t.obj_id= #{objId}


    and t.obj_person_id= #{objPersonId}


    and t.contract_name= #{contractName}


    and t.contract_name like concat('%',#{contractNameLike},'%')


    and t.start_time= #{startTime}


    and t.end_time <= #{endTime}


    and t.create_time > #{queryStartTime}


    and t.create_time < #{queryEndTime}


    and t.state= #{state}


    and t.state not in

        #{item}



    and t.contract_code= #{contractCode}


    and t.contract_code like concat('%',#{contractCodeLike},'%')


    and t.obj_type= #{objType}


    and t.operator_link= #{operatorLink}


    and t.contract_parent_id= #{contractParentId}


    and tt.contract_code like concat('%',#{parentContractCodeLike},'%')


    and t.partya_id = #{partyaId}


    and t.template_id = #{templateId}


    and ifnull(ctt.category, '2') = #{category}


    and ifnull(ctt.category, '2') in

        #{item}



    and t.pay_mode = #{payMode}


    and exists (select 1 from contract_change_plan cp where cp.contract_id = t.contract_id and cp.status_cd = '0')


    and not exists (select 1 from contract_change_plan cp where cp.contract_id = t.contract_id and cp.status_cd = '0')


    and (t.contract_name like concat('%',#{searchText},'%')
    or t.contract_code like concat('%',#{searchText},'%')
    or t.party_b like concat('%',#{searchText},'%')
    or t.party_a like concat('%',#{searchText},'%'))


    and t.end_time >= #{endTimeBegin}


    and t.end_time <= #{endTimeEnd}

select t.obj_id ownerId,count(t.contract_id) contractCount from contract t where t.status_cd = '0' and t.obj_id in
#{item}
group by t.obj_id

select count(1) total, ifnull(sum(case when t.state = '22' then 1 else 0 end), 0) effective, ifnull(sum(case when t.state = '11' then 1 else 0 end), 0) auditing, ifnull(sum(case when t.state = '10' then 1 else 0 end), 0) draft, ifnull(sum(t.amount), 0) totalAmount, ifnull(sum(case when ifnull(ctt.category, '2') = '1' then 1 else 0 end), 0) rentCount, ifnull(sum(case when ifnull(ctt.category, '2') = '2' then 1 else 0 end), 0) purchaseCount, ifnull(sum(case when ifnull(ctt.category, '2') = '3' then 1 else 0 end), 0) maintainCount, ifnull(sum(case when ifnull(ctt.category, '2') = '1' then t.amount else 0 end), 0) rentAmount, ifnull(sum(case when ifnull(ctt.category, '2') = '2' then t.amount else 0 end), 0) purchaseAmount, ifnull(sum(case when ifnull(ctt.category, '2') = '3' then t.amount else 0 end), 0) maintainAmount, (select count(distinct cr.room_id) from contract_room cr join contract c2 on c2.contract_id = cr.contract_id and c2.status_cd = '0' where cr.status_cd = '0'
and cr.store_id = #{storeId}
) roomCount from contract t left join contract_type_template ctt on t.template_id = ctt.template_id and ctt.status_cd = '0' and ctt.store_id = t.store_id where t.status_cd = '0'
and t.store_id = #{storeId}

select c.contract_id contractId, c.contract_code contractCode, c.contract_name contractName, c.pay_mode payMode, c.amount amount, c.start_time startTime, c.end_time endTime, c.operator operator, c.party_b partyB, c.state state, ctt.template_name templateName, ifnull(ctt.category, '2') category, ifnull(sum(case when p.pay_state = '1' then p.plan_amount else 0 end), 0) paidAmount, ifnull(sum(case when ifnull(p.pay_state, '0') <> '1' then p.plan_amount else 0 end), 0) unpaidAmount, ifnull(sum(case when p.pay_state = '2' or (ifnull(p.pay_state,'0') = '0' and p.plan_time < now()) then 1 else 0 end), 0) overdueCount, ifnull(sum(case when p.pay_state = '1' then 1 else 0 end), 0) paidCount, count(p.plan_id) planCount, min(case when ifnull(p.pay_state, '0') <> '1' then p.plan_time end) nextPlanTime, (select p2.plan_name from contract_collection_plan p2 where p2.contract_id = c.contract_id and p2.status_cd = '0' and ifnull(p2.pay_state, '0') <> '1' order by p2.plan_time asc limit 0, 1) nextPlanName from contract c left join contract_type_template ctt on c.template_id = ctt.template_id and ctt.status_cd = '0' and ctt.store_id = c.store_id left join contract_collection_plan p on p.contract_id = c.contract_id and p.status_cd = '0' where c.status_cd = '0'
and c.store_id = #{storeId}
and ifnull(ctt.category, '2') = #{category}
and ifnull(ctt.category, '2') in
#{item}
and exists (select 1 from contract_collection_plan p3 where p3.contract_id = c.contract_id and p3.status_cd = '0' and ifnull(p3.pay_state, '0') = #{payState})
and (c.contract_code like concat('%', #{searchText}, '%') or c.contract_name like concat('%', #{searchText}, '%') or c.party_b like concat('%', #{searchText}, '%'))
and c.contract_id = #{contractId}
group by c.contract_id, c.contract_code, c.contract_name, c.pay_mode, c.amount, c.start_time, c.end_time, c.operator, c.party_b, c.state, ctt.template_name, ctt.category order by c.create_time desc
limit #{page}, #{row}

select count(1) count from ( select c.contract_id from contract c left join contract_type_template ctt on c.template_id = ctt.template_id and ctt.status_cd = '0' and ctt.store_id = c.store_id where c.status_cd = '0'
and c.store_id = #{storeId}
and ifnull(ctt.category, '2') = #{category}
and ifnull(ctt.category, '2') in
#{item}
and exists (select 1 from contract_collection_plan p3 where p3.contract_id = c.contract_id and p3.status_cd = '0' and ifnull(p3.pay_state, '0') = #{payState})
and (c.contract_code like concat('%', #{searchText}, '%') or c.contract_name like concat('%', #{searchText}, '%') or c.party_b like concat('%', #{searchText}, '%'))
and c.contract_id = #{contractId}
group by c.contract_id ) tmp

select c.contract_id contractId, c.contract_code contractCode, c.contract_name contractName, c.end_time endTime, c.start_time startTime, c.amount amount, c.operator operator, c.party_b partyB, c.state state, ctt.template_name templateName, ifnull(ctt.category, '2') category, c.store_id storeId, datediff(c.end_time, now()) daysLeft, (select count(1) from contract_remind_log l where l.contract_id = c.contract_id and l.status_cd = '0') remindCount from contract c left join contract_type_template ctt on c.template_id = ctt.template_id and ctt.status_cd = '0' and ctt.store_id = c.store_id where c.status_cd = '0' and c.state = '22' and c.end_time is not null
and c.store_id = #{storeId}
and ifnull(ctt.category, '2') = #{category}
and (c.contract_code like concat('%', #{searchText}, '%') or c.contract_name like concat('%', #{searchText}, '%') or c.party_b like concat('%', #{searchText}, '%'))
and datediff(c.end_time, now()) <= ifnull(#{days}, 30)
and datediff(c.end_time, now()) >= 0
order by daysLeft asc
limit #{page}, #{row}

select count(1) count from contract c left join contract_type_template ctt on c.template_id = ctt.template_id and ctt.status_cd = '0' and ctt.store_id = c.store_id where c.status_cd = '0' and c.state = '22' and c.end_time is not null
and c.store_id = #{storeId}
and ifnull(ctt.category, '2') = #{category}
and (c.contract_code like concat('%', #{searchText}, '%') or c.contract_name like concat('%', #{searchText}, '%') or c.party_b like concat('%', #{searchText}, '%'))
and datediff(c.end_time, now()) <= ifnull(#{days}, 30)
and datediff(c.end_time, now()) >= 0

select t.log_id logId, t.contract_id contractId, t.remind_type remindType, t.channel channel, t.send_time sendTime, t.receive_tel receiveTel, t.content content, t.status_cd statusCd, t.create_time createTime from contract_remind_log t where t.status_cd = '0'
and t.contract_id = #{contractId}
and t.contract_id in
#{item}
order by t.create_time desc
